try{savedView=JSON.parse(localStorage.getItem(viewKey)||'{}')||{};}catch{}
if(Number(localStorage.getItem('frame-comfy-port'))===8189)localStorage.setItem('frame-comfy-port','8188');if(Number(savedView.port)===8189)savedView.port=8188;for(const form of Object.values(savedView.forms||{}))if(Number(form?.port)===8189)form.port=8188;
