$('#toolProjectRename').onclick=async()=>{try{const p=await api('/projects/'+projectId(),{name:$('#toolProjectName').value});state.projects=state.projects.map(x=>x.id===p.id?{...x,...p}:x);$('#toolProjectName').value='';drawProjects();drawHistory();}catch(e){$('#toolProjectNote').textContent=e.message;}};
const historyMoveDialog=document.createElement('dialog');historyMoveDialog.id='toolHistoryMoveDialog';historyMoveDialog.style.cssText='width:min(520px,92vw);background:#172334;color:inherit;border:1px solid #40556b;border-radius:14px;padding:22px';historyMoveDialog.innerHTML='<h2>移动这条履历</h2><p id="toolMoveSource"></p><label>目标项目<select id="toolMoveDestination" aria-label="目标项目"></select></label><p id="toolMoveStatus" role="status"></p><div style="display:flex;gap:10px"><button type="button" id="toolMoveSubmit">移动这条履历</button><button type="button" id="toolMoveCancel">取消</button></div>';document.body.append(historyMoveDialog);let movingJobId=null;
