$('#toolMoveCancel').onclick=()=>historyMoveDialog.close();$('#toolMoveSubmit').onclick=async()=>{const button=$('#toolMoveSubmit');button.disabled=true;try{const moved=await api('/jobs/'+movingJobId+'/move',{target_project_id:$('#toolMoveDestination').value});[state.jobs,state.projects]=await Promise.all([api('/jobs'),api('/projects')]);if(state.selected===movingJobId){state.selected=null;state.projectSelected[projectId()]=null;selectKindHistory();}drawHistory();persistView();historyMoveDialog.close();$('#historyMessage').textContent='已将这条履历移入 '+(state.projects.find(p=>p.id===moved.tool_project_id)?.name||'目标项目')+'。';}catch(e){$('#toolMoveStatus').textContent=e.message;}finally{button.disabled=false;}};
function persistView(){if(!viewReady)return;try{const forms={};for(const [kind,form]of Object.entries(state.forms))forms[kind]={...form,files:[],videoFile:null};localStorage.setItem(viewKey,JSON.stringify({kind:state.kind,selected:state.selected,forms,projectByKind:state.projectByKind,projectForms:Object.fromEntries(Object.entries(state.projectForms).map(([id,f])=>[id,{...f,files:[],videoFile:null}])),projectSelected:state.projectSelected,scrollY:window.scrollY,port:$('#toolPort').value}));}catch{}}
