function renderRatioCards(video){const select=$('#toolSize'),current=select.value,[cw,ch]=(current||'1024x1024').split('x').map(Number),original=state.sourceSize||{width:cw,height:ch},role=!!new URLSearchParams(location.search).get('role_view'),key='frame-tool-output-ratio-'+state.kind;state.sourceSize??=original;let ratio=role?'original':localStorage.getItem(key)||'original';const preset=ToolSizes.ratios.find(r=>r.id===ratio),source=preset?{width:preset.w*512,height:preset.h*512}:original;const choices=!video&&!role?[1280,1920,2560,3840].map(long=>{const scale=long/Math.max(source.width,source.height);return Math.round(source.width*scale)+'x'+Math.round(source.height*scale);}):SourceSizeChoices.choices(source.width,source.height,video);const defaultSize=choices[Math.floor(choices.length/2)];if(video&&!choices.includes('608x352'))choices.push('608x352');choices.sort((a,b)=>{const [aw,ah]=a.split('x').map(Number),[bw,bh]=b.split('x').map(Number);return aw*ah-bw*bh||aw-bw||ah-bh;});select.replaceChildren();for(const size of choices){const o=document.createElement('option');o.value=size;const resolutionLabel=!video&&!role?({1280:'720P',1920:'1080P',2560:'2.5K',3840:'4K'})[Math.max(...size.split('x').map(Number))]:null;o.textContent=(resolutionLabel?resolutionLabel+' · ':'')+size.replace('x',' × ')+' px'+(!resolutionLabel&&Math.max(...size.split('x').map(Number))===3840?' · 4K':'');o.dataset.quality='history';select.append(o);}select.value=choices.includes(current)?current:defaultSize;const box=$('#toolRatios');box.hidden=role||['image-upscale','upscale-video'].includes(state.kind);box.style.cssText='display:flex;gap:8px;flex-wrap:wrap;margin:10px 0';if(box.hidden)box.style.display='none';box.replaceChildren();for(const r of [{id:'original',w:original.width,h:original.height},...ToolSizes.ratios]){const button=document.createElement('button');button.type='button';button.setAttribute('aria-pressed',String(r.id===ratio));button.setAttribute('aria-label',r.id+' 比例');button.style.cssText='width:auto;min-width:72px;padding:8px 12px;white-space:nowrap';if(r.id===ratio)button.className='primary';button.textContent=r.id==='original'?'原图比例':r.id;button.onclick=()=>{localStorage.setItem(key,r.id);renderRatioCards(video);remember();};box.append(button);}$('#toolSizeHint').textContent=(preset?'画面比例 '+ratio:'按原图比例')+' · 实际生成尺寸：'+select.value.replace('x',' × ')+' px'+(!video&&Math.max(...select.value.split('x').map(Number))>1536?' · 自动超分至目标尺寸':'');}



