function remember(){if(!viewReady)return;state.forms[state.kind]={prompt:$('#toolPrompt').value,negative:$('#toolNegative').value,size:$('#toolSize').value,ratio:$('#toolRatios [aria-pressed=true]')?.getAttribute('aria-label')?.split(' ')[0],quality:$('#toolQuality').value,files:[...state.files],savedUploads:[...state.savedUploads],reference_mode:$('#videoReferenceMode').value,video_quality:$('#toolVideoQuality').value,duration:$('#toolDuration').value,upscale_target:$('#toolUpscaleTarget').value,videoFile:state.videoFile,videoUploadId:state.videoUploadId,upscaleBinding:state.upscaleBinding,view_prompt:$('#toolViewPrompt').value,sourceSize:state.sourceSize,size_mode:$('#generationSizeMode')?.value||'native',native_long:$('#generationNativeLong')?.value||'768',image_model:$('#toolImageModel').value,port:Number($('#toolPort').value)};state.projectForms[projectId()]=state.forms[state.kind];state.projectSelected[projectId()]=state.selected;persistView();}
