function selectKindHistory(){const jobs=state.jobs.filter(belongs),selected=jobs.find(j=>j.id===state.selected)||jobs[0];state.selected=selected?.id||null;if(selected)show(selected);else{shownMedia='';$('#toolPreview').replaceChildren();const p=document.createElement('p');p.className='subtle';p.textContent='生成完成后在这里查看';$('#toolPreview').append(p);$('#toolLinks').replaceChildren();$('#toolTiming').textContent='';$('#jobStatus').textContent='';$('#toolProgress').hidden=true;$('#toolJobSettings').textContent='';$('#toolJobPrompt').textContent='';}drawHistory();syncGenerateButton();}
function historyDuration(j){const seconds=j.timing?.elapsed_seconds??((Date.parse(j.finished_at||new Date().toISOString())-Date.parse(j.created_at))/1000);return (active(j)?'已用 ':'耗时 ')+durationText(seconds);}
function showDeleteUndo(job){const box=$('#toolDeleteStatus');box.replaceChildren();const text=document.createElement('span');text.textContent='记录已删除 ';const undo=document.createElement('button');undo.type='button';undo.textContent='撤销删除';undo.onclick=async()=>{undo.disabled=true;try{const restored=await api('/jobs/'+job.id+'/restore',{});if(!state.jobs.some(j=>j.id===restored.id))state.jobs.push(restored);state.jobs.sort((a,b)=>b.created_at.localeCompare(a.created_at));drawHistory();box.textContent='记录已恢复';}catch(e){box.textContent=e.message;}};box.append(text,undo);}
function drawHistory(){
 const box=$('#toolHistory'),jobs=state.jobs.filter(belongs),ids=new Set(jobs.map(j=>j.id));
 $('#toolHistoryTitle').textContent=projectName()+' · 履历';drawProjects();
 if(!jobs.length){box.textContent='这个项目还没有履历，填写提示词后开始生成。';return;}
 if(!box.querySelector('.tool-history-row'))box.replaceChildren();
 for(const row of [...box.children])if(!ids.has(row.dataset.jobId)){row.querySelector('video')?.pause();row.remove();}
 jobs.forEach((j,index)=>{
  let row=[...box.children].find(x=>x.dataset.jobId===j.id);
  if(!row){row=document.createElement('div');row.className='tool-history-row';row.dataset.jobId=j.id;const preview=document.createElement('div');preview.className='tool-history-media';const b=document.createElement('button');b.type='button';b.className='tool-history-item';const remove=document.createElement('button');remove.type='button';remove.className='tool-history-delete';remove.textContent='删除';row.append(preview,b,remove);}
  if(!row.querySelector('.tool-history-move')){const actions=document.createElement('div');actions.className='tool-history-actions';const move=document.createElement('button');move.type='button';move.className='tool-history-move';move.textContent='移到项目';actions.append(move,row.querySelector('.tool-history-delete'));row.append(actions);}row.querySelector('.tool-history-move').onclick=()=>openHistoryMove(j);
  const preview=row.querySelector('.tool-history-media'),key=j.status==='completed'&&j.result_url?j.result_url:'';
  if(preview.dataset.mediaKey!==key){preview.replaceChildren();preview.dataset.mediaKey=key;
   if(key){const video=j.kind.endsWith('video'),media=document.createElement(video?'video':'img');media.src=key;
    if(video){media.controls=true;media.preload='metadata';media.playsInline=true;media.muted=true;media.addEventListener('loadedmetadata',()=>{if(Number.isFinite(media.duration)&&media.duration>0)media.currentTime=Math.min(0.1,media.duration/2);},{once:true});media.setAttribute('aria-label',names[j.kind]+'生成记录视频预览');media.addEventListener('play',()=>box.querySelectorAll('video').forEach(v=>{if(v!==media)v.pause();}));}
    else{media.alt=names[j.kind]+'生成记录缩略图';media.loading='lazy';media.onclick=()=>restoreHistory(j);}
    preview.append(media);
   }
  }
  if(!key&&preview.textContent!==(labels[j.status]||j.status))preview.textContent=labels[j.status]||j.status;
  const b=row.querySelector('.tool-history-item');b.textContent='V'+(j.tool_revision||jobs.length-index)+' · '+(names[j.kind]||j.kind)+' · '+(labels[j.status]||j.status)+' · '+historyDuration(j)+' · '+generationGpuLabel(j)+' · '+new Date(j.created_at).toLocaleString('zh-CN')+'\n'+String(j.prompt||'').slice(0,70);b.onclick=()=>restoreHistory(j);
  const remove=row.querySelector('.tool-history-delete');remove.disabled=active(j);remove.title=active(j)?'请先停止生成':'删除此生成记录（可撤销）';remove.onclick=async()=>{remove.disabled=true;try{await api('/jobs/'+j.id+'/delete',{});state.jobs=state.jobs.filter(x=>x.id!==j.id);if(state.selected===j.id)selectKindHistory();drawHistory();showDeleteUndo(j);}catch(e){$('#historyMessage').textContent=e.message;remove.disabled=false;}};
  if(box.children[index]!==row)box.insertBefore(row,box.children[index]||null);
 });
}
function durationText(seconds){if(!Number.isFinite(seconds))return '—';const s=Math.max(0,Math.round(seconds));return s>=60?Math.floor(s/60)+'分'+s%60+'秒':s+'秒';}
function updateTiming(){const j=state.jobs.find(j=>j.id===state.selected);if(!j)return;const timing=j.timing||{},p=j.status==='disconnected'?{label:'ComfyUI连接中断'}:j.progress||{},ongoing=active(j),delta=ongoing&&j.timing_received_at?(Date.now()-j.timing_received_at)/1000:0;const elapsed=timing.elapsed_seconds??Math.max(0,((j.finished_at?Date.parse(j.finished_at):Date.now())-Date.parse(j.created_at))/1000);const parts=[p.label||labels[j.status]||j.status,'已用 '+durationText(elapsed+delta)];if(j.kind==='upscale-video'&&p.total)parts.push('画面段 '+(p.completed||0)+'/'+p.total);if(p.total_steps&&p.phase==='sampling')parts.push('采样 '+p.step+'/'+p.total_steps+' 步');
if(ongoing){if(j.status==='disconnected')parts.push('生成已中断，等待服务恢复后确认任务');else if(j.status==='queued')parts.push('排队时间不计入生成预估');else if(Number.isFinite(timing.remaining_seconds)){parts.push('预计剩余 '+durationText(Math.max(5,timing.remaining_seconds-delta))+'（含解码保存，动态调整）');}else if(Number.isFinite(timing.sampling_remaining_seconds)&&p.phase==='sampling'){const remaining=timing.sampling_remaining_seconds-delta;parts.push(remaining>0?'采样预计剩余 '+durationText(remaining)+'，之后还需解码保存':'采样预估已到，仍在计算');}else if(timing.remaining_range_seconds){const range=timing.remaining_range_seconds.map(v=>Math.max(0,v-delta));parts.push(range[1]>0?'预计剩余 '+durationText((range[0]+range[1])/2):'已超过历史预估，仍在运行');}else parts.push('预计剩余：等待采样数据或同类历史记录');}
if(Number.isFinite(timing.postprocessing_seconds))parts.push('采样后处理耗时 '+durationText(timing.postprocessing_seconds));else if(ongoing&&Number.isFinite(timing.postprocessing_estimate_seconds))parts.push('采样后处理预计 '+durationText(timing.postprocessing_estimate_seconds));const range=timing.estimated_total_range_seconds;if(ongoing&&j.status!=='disconnected'&&range)parts.push('同类历史预计生成 '+durationText((range[0]+range[1])/2)+'（'+timing.estimate_samples+'次记录）');$('#toolTiming').textContent=parts.join(' · ');const bar=$('#toolProgress');bar.hidden=!ongoing||(!(p.phase==='sampling'&&p.total_steps)&&!(j.kind==='upscale-video'&&p.total));if(!bar.hidden){bar.max=p.total_steps||p.total;bar.value=p.step||p.completed||0;}$('#jobStatus').textContent=p.label||labels[j.status]||j.status;const loading=$('#toolPreview .tool-loader');if(loading){loading.querySelector('.tool-loader-label').textContent=j.status==='disconnected'?'ComfyUI连接中断':j.status==='queued'?'已排队，等待开始':(j.kind.endsWith('video')?'正在生成视频':'正在生成图片')+' · '+(p.label||labels[j.status]||'');loading.querySelector('.tool-loader-note').textContent=parts.slice(1).join(' · ');}}
function createLoading(j){const box=document.createElement('div');box.className='tool-loader';const mark=document.createElement('div');mark.className='tool-loader-mark';mark.setAttribute('aria-hidden','true');const label=document.createElement('p');label.className='tool-loader-label';label.textContent=j.status==='queued'?'已排队，等待开始':j.kind.endsWith('video')?'正在生成视频':'正在生成图片';const note=document.createElement('p');note.className='tool-loader-note';note.textContent='正在获取生成进度…';box.append(mark,label,note);return box;}
