async function load(){try{[state.jobs,state.projects]=await Promise.all([api('/jobs'),api('/projects')]);if(!state.projects.some(p=>p.id===projectId()&&p.kind===state.kind))state.projectByKind[state.kind]=state.projects.find(p=>p.kind===state.kind)?.id||'legacy-'+state.kind;drawProjects();selectKindHistory();$('#historyMessage').textContent='';}catch(e){$('#historyMessage').textContent='读取记录失败：'+e.message;}finally{state.loaded=true;drawProjects();syncGenerateButton();}}
function selectedUploads(){const all=[...state.savedUploads.map((id,index)=>({id,index,saved:true})),...state.files.map((file,index)=>({file,index,saved:false}))];return state.kind==='image-video'?all:all.slice(0,1);}
