function showComfyStatus(result){const button=$('#toolComfyStart'),label=$('#toolComfyStatus');button.disabled=result.status==='starting'||result.status==='running';button.textContent=result.status==='running'?'ComfyUI 已启动':result.status==='starting'?'正在启动 ComfyUI…':'启动 ComfyUI';label.textContent=result.status==='running'?'已连接本机ComfyUI · 端口 '+result.port:result.status==='starting'?'正在加载ComfyUI，启动完成后即可生成。':result.error||'ComfyUI未连接，点击上方启动按钮。';if(result.status==='running'){$('#toolComfyOpen').href=result.url+'/';if(comfyStarting){comfyStarting=false;$('#toolMessage').textContent='ComfyUI已启动，可以开始生成。';}clearInterval(comfyTimer);comfyTimer=null;}else if(result.status==='failed'||result.status==='offline'){comfyStarting=false;clearInterval(comfyTimer);comfyTimer=null;}else if(result.status==='starting'){comfyStarting=true;if(!comfyTimer)comfyTimer=setInterval(checkComfy,3000);}}
