$('#toolComfyStart').onclick=async()=>{if(comfyStarting)return;comfyStarting=true;$('#toolComfyStart').disabled=true;$('#toolComfyStart').textContent='正在启动 ComfyUI…';try{const result=await api('/comfy/start',{port:Number($('#toolPort').value||8188)});showComfyStatus(result);if(result.status==='starting'&&!comfyTimer)comfyTimer=setInterval(checkComfy,3000);}catch(e){comfyStarting=false;$('#toolComfyStart').disabled=false;$('#toolComfyStart').textContent='启动 ComfyUI';$('#toolComfyStatus').textContent='启动失败：'+e.message;}};
