 const projectSelect=$('#toolSourceProject'),characterSelect=$('#toolSourceCharacter'),imageSelect=$('#toolSourceImage'),preview=$('#toolProjectImagePreview'),use=$('#toolUseProjectImage'),status=$('#toolProjectImageStatus');let project=null,items=[],selectionVersion=0,editingIndex=null;let externalReceive=null;const assetType=$('#toolSourceAssetType');
